contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes two amounts and exercises addToBalance and withdrawBalance
    function run(uint addAmt1, uint addAmt2) public payable {
        // ensure this test contract can send the requested ethers
        require(address(this).balance >= addAmt1 + addAmt2);

        // Read initial observed values
        uint before_balance_record = c.getBalance(address(this));
        uint before_contract_balance = address(c).balance;

        // First add
        c.addToBalance{value: addAmt1}();
        uint mid_balance_record = c.getBalance(address(this));
        uint mid_contract_balance = address(c).balance;

        // The recorded balance must increase by exactly addAmt1 and contract's balance too
        // Second add
        c.addToBalance{value: addAmt2}();
        uint after_balance_record = c.getBalance(address(this));
        uint after_contract_balance = address(c).balance;

        // Now attempt withdraw; capture whether it reverts
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint final_record_balance = c.getBalance(address(this));
        uint final_contract_balance = address(c).balance;

        // General rule asserted as a single expression:
        // 1) Each add increased the recorded balance and contract balance by the exact amounts
        // 2) After successful withdraw (not reverted): recorded balance becomes zero and contract balance decreased by the withdrawn amount
        // 3) If withdraw reverted, balances remain unchanged from before withdraw
        assert(
            // check first add effect
            mid_balance_record == before_balance_record + addAmt1
            && mid_contract_balance == before_contract_balance + addAmt1
            // check second add effect
            && after_balance_record == mid_balance_record + addAmt2
            && after_contract_balance == mid_contract_balance + addAmt2
            // check withdraw outcome correlates with revert flag
            && (
                (!reverted
                    && final_record_balance == 0
                    && final_contract_balance + (after_balance_record) == after_contract_balance)
                || (reverted
                    && final_record_balance == after_balance_record
                    && final_contract_balance == after_contract_balance)
               )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to send to addToBalance and a flag to optionally call withdraw first
    function run(uint amount, bool callWithdrawFirst) public payable {
        require(address(this).balance >= amount);

        // Optionally perform a prior withdraw to exercise more states (withdraw may revert if balance=0 but that's fine)
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read before-values
        uint beforeRecorded = c.getBalance(address(this));
        uint beforeContractBal = address(c).balance;

        // Call addToBalance sending 'amount' wei and record whether it reverted
        bool addReverted;
        try c.addToBalance{value: amount}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // Read after-values
        uint afterRecorded = c.getBalance(address(this));
        uint afterContractBal = address(c).balance;

        // General invariant:
        // - If addToBalance succeeded: recorded balance increased by exactly amount and contract balance increased by exactly amount.
        // - If addToBalance reverted: recorded balance and contract balance are unchanged.
        assert(
            (!addReverted && afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount)
            || (addReverted && afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
        );
    }

    // Allow the contract to receive funds when c.withdrawBalance sends Ether to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will: optionally deposit some ether into c on behalf of this contract, then attempt withdraw,
    // and assert the general rule described above.
    function run(uint depositAmount, bool doDeposit) public payable {
        require(address(this).balance >= depositAmount);

        // read balance before any operations
        uint beforeRecorded = c.getBalance(address(this));
        uint beforeContractEth = address(c).balance;

        // optionally deposit ETH to c using addToBalance
        if (doDeposit) {
            // send depositAmount wei
            c.addToBalance{value: depositAmount}();
        }

        // record values just before withdraw attempt
        uint preWithdrawRecorded = c.getBalance(address(this));
        uint preWithdrawContractEth = address(c).balance;

        // attempt withdraw and capture whether it reverted
        bool withdrew;
        try c.withdrawBalance() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // read after-state values (view calls allowed here)
        uint afterRecorded = c.getBalance(address(this));
        uint afterContractEth = address(c).balance;

        // General rule:
        // If withdrawBalance succeeded then (1) recorded balance for this contract's address is zero,
        // and (2) the contract's ETH balance decreased by at least the amount that was recorded for this caller
        // immediately before the withdraw (preWithdrawRecorded). If withdraw reverted, we place no constraint.
        assert(!withdrew || (afterRecorded == 0 && preWithdrawContractEth >= afterContractEth && (preWithdrawContractEth - afterContractEth) >= preWithdrawRecorded));
    }

    // Allow contract to receive ETH when c sends value back
    receive() external payable {}
}

